req = urllib.request.Request("http://localhost:1337/json")
targets = json.loads(urllib.request.urlopen(req).read())
amazon_pages = [t for t in targets if t["type"] == "page" and "amazon" in t.get("url", "")]
print(f"Found {len(amazon_pages)} Amazon page tabs")
for p in amazon_pages:
    print(f"  - {p['url'][:90]}")

BROWSER_WS = "ws://localhost:1337/devtools/browser/1d4c6d10-5133-48e7-9253-9b8167a03441"
ws = websocket.create_connection(BROWSER_WS, timeout=20, suppress_origin=True)

_id = [0]
def cmd(method, params=None, session_id=None):
    _id[0] += 1
    msg = {"id": _id[0], "method": method}
    if params:
        msg["params"] = params
    if session_id:
        msg["sessionId"] = session_id
    ws.send(json.dumps(msg))
    while True:
        r = json.loads(ws.recv())
        if r.get("id") == _id[0]:
            return r

# Discover all targets via Target.getTargets
all_targets = cmd("Target.getTargets").get("result", {}).get("targetInfos", [])
amazon_targets = [t for t in all_targets if "amazon" in t.get("url", "").lower()]
print(f"\nAmazon targets via CDP: {len(amazon_targets)}")
for t in amazon_targets:
    print(f"  [{t['type']}] {t.get('url','')[:90]}")

# Attach to each Amazon page and clear its storage
cleared_summary = []
for t in amazon_targets:
    if t["type"] not in ("page", "iframe", "service_worker"):
        continue
    target_id = t["targetId"]
    r = cmd("Target.attachToTarget", {"targetId": target_id, "flatten": True})
    if "error" in r:
        print(f"  attach failed for {t.get('url','')[:60]}: {r['error']}")
        continue
    session_id = r["result"]["sessionId"]

    # Storage.clearDataForOrigin works correctly when called from a page session
    origin_url = t.get("url", "")
    try:
        from urllib.parse import urlparse
        p = urlparse(origin_url)
        origin = f"{p.scheme}://{p.netloc}"
    except Exception:
        origin = ""

    if origin:
        cr = cmd("Storage.clearDataForOrigin", {"origin": origin, "storageTypes": "all"}, session_id=session_id)
        ok = "error" not in cr
        cleared_summary.append((origin, ok, cr.get("error")))
        print(f"  clearDataForOrigin {origin}: {'OK' if ok else cr.get('error')}")

    # For pages, also try in-page: localStorage.clear(), sessionStorage.clear(), service worker unregister
    if t["type"] == "page":
        js = """
        (async () => {
            const out = {};
            try { localStorage.clear(); out.localStorage = 'cleared'; } catch(e) { out.localStorage = e.message; }
            try { sessionStorage.clear(); out.sessionStorage = 'cleared'; } catch(e) { out.sessionStorage = e.message; }
            try {
                const dbs = await indexedDB.databases();
                for (const db of dbs) { indexedDB.deleteDatabase(db.name); }
                out.indexedDB = 'cleared ' + dbs.length;
            } catch(e) { out.indexedDB = e.message; }
            try {
                const regs = await navigator.serviceWorker.getRegistrations();
                for (const r of regs) { await r.unregister(); }
                out.serviceWorkers = 'unregistered ' + regs.length;
            } catch(e) { out.serviceWorkers = e.message; }
            try {
                const keys = await caches.keys();
                for (const k of keys) { await caches.delete(k); }
                out.cacheStorage = 'cleared ' + keys.length;
            } catch(e) { out.cacheStorage = e.message; }
            return out;
        })()
        """
        er = cmd("Runtime.evaluate", {
            "expression": js,
            "awaitPromise": True,
            "returnByValue": True,
        }, session_id=session_id)
        result_val = er.get("result", {}).get("result", {}).get("value")
        print(f"    in-page clear result: {result_val}")

